WITH cleaned AS (SELECT *, FLOOR(quantity) AS quantity_whole FROM inventory WHERE last_restock >= TO_DATE('2023-08-12') AND quantity IS NOT NULL), with_dims AS (SELECT s.*, b.category, b.price FROM cleaned s LEFT JOIN products b ON s.product_id = b.id), latest AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY store_id, product_id ORDER BY quantity ASC, id ASC) AS rank_in_group FROM with_dims QUALIFY rank_in_group = 1), with_windows AS (SELECT id, product_id, last_restock, quantity_whole, category, price, rank_in_group, LAST_VALUE(price, TRUE) OVER (PARTITION BY store_id ORDER BY quantity ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_price, LEAD(price, 2) OVER w_ordered AS next_price, LAG(quantity, 2) OVER w_ordered AS prev_quantity FROM latest WHERE store_id IN (1, 2, 4, 6) WINDOW w_ordered AS (ORDER BY price ASC, id ASC)), metrics AS (SELECT *, LAG(last_known_price, 1) OVER (PARTITION BY category, product_id ORDER BY prev_quantity ASC, id ASC) AS prev_last_known_price, NTILE(4) OVER (PARTITION BY product_id ORDER BY price ASC, id ASC) AS price_bucket, ROW_NUMBER() OVER (PARTITION BY category ORDER BY next_price ASC, id ASC) AS event_seq, LAST_VALUE(prev_quantity, TRUE) OVER (PARTITION BY category ORDER BY price ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_prev_quantity FROM with_windows), with_dims_inventory AS (SELECT e.*, b.product_name, b.cost FROM metrics e INNER JOIN products b ON e.product_id = b.id), wide AS (SELECT * FROM (SELECT product_id, category, cost FROM with_dims_inventory) src PIVOT (AVG(cost) AS value_sum FOR category IN ('Sports', 'Fashion'))) SELECT s.product_id, s.Sports, s.Fashion, (SELECT SUM(t2.quantity) FROM inventory t2 WHERE t2.product_id = s.product_id) AS sum_inventory_quantity FROM wide s ORDER BY sum_inventory_quantity DESC NULLS LAST;
